package com.example.notesmaker.data.local

import androidx.room.Entity
import androidx.room.PrimaryKey

/**
 * Room entity representing a note record in table "notes".
 *
 * @param id Primary key auto-generated by Room.
 * @param title Note title text.
 * @param body Detailed note content text.
 * @param timestamp Epoch timestamp in milliseconds when created/updated.
 * @param isPinned Flag indicating whether the note is pinned to top.
 */
@Entity(tableName = "notes")
data class Note(
    @PrimaryKey(autoGenerate = true)
    val id: Long = 0,
    val title: String,
    val body: String,
    val timestamp: Long = System.currentTimeMillis(),
    val isPinned: Boolean = false
)

